const target = msg.metadata && msg.metadata.target;

if (!target ||
    !target.client_specific ||
    !target.client_specific.api_key ||
    !target.client_specific.base_url) {
    node.error("CIM not configured on this connection");
    return null;
}

msg.url = target.client_specific.base_url + "/cases";

msg.headers = {
    "Authorization": "Bearer " + target.client_specific.api_key,
    "Content-Type":  "application/json",
    "Accept":        "application/json"
};
return msg;
